#!/usr/bin/bash
# ==== File generated by ./generate_runs.py, do not edit! ====

set -euo pipefail
JLM_PATH="${JLM_PATH:-jlm}"
PARALLEL_TASKS="${PARALLEL_TASKS:-1}"
TMP_STATS_DIR="${TMP_STATS_DIR:-statistics}"
echo "Run started at $(date)" | tee -a "statistics-out/sroa-raw-ip-omf-5.echo"
echo "Benchmark checkout:" | tee -a "statistics-out/sroa-raw-ip-omf-5.echo"
git rev-parse HEAD | tee -a "statistics-out/sroa-raw-ip-omf-5.echo"
git status --porcelain | tee -a "statistics-out/sroa-raw-ip-omf-5.echo"
echo "Jlm checkout:" | tee -a "statistics-out/sroa-raw-ip-omf-5.echo"
git -C "${JLM_PATH}" rev-parse HEAD | tee -a "statistics-out/sroa-raw-ip-omf-5.echo"
git -C "${JLM_PATH}" status --porcelain | tee -a "statistics-out/sroa-raw-ip-omf-5.echo"
set -x

if [ -f "statistics-out/sroa-raw-ip-omf-5.csv" ]; then
echo "Configuration already done" >> "statistics-out/sroa-raw-ip-omf-5.echo"
exit 0
fi

export JLM_DISABLE_FUNCTION_SIMPLE_ALLOCA_ALLOWLIST=1
export JLM_DISABLE_CALL_SIMPLE_ALLOCA_ALLOWLIST=1
export JLM_DISABLE_EXTERN_SIMPLE_ALLOCA_ALLOWLIST=1
export JLM_DISABLE_CONSTANT_MEMORY_BLOCKING=1
export JLM_DISABLE_READ_ONLY_DETECTION=1
export JLM_DISABLE_OPERATION_SIZE_BLOCKING=1
export JLM_DISABLE_MEMORY_STATE_DISTRIBUTION_STATISTICS=1

./benchmark.py "--jlm-opt=${JLM_PATH}/build-release/jlm-opt" --llvmbin=/usr/lib/llvm-18/bin --sources=sources/sources.json -j="${PARALLEL_TASKS}" --statsdir="${TMP_STATS_DIR}" --full-spec '--filter=5\d\d\.' --filter=emacs --filter=gdb --filter=ghostscript --filter=sendmail --noStrictAliasing --optSroa --pre-jlm-name sroa --regionAwareModRef --jlm-name sroa-raw-ip-omf-5 --nullOutput

echo "Done with status code $? at $(date)" >> "statistics-out/sroa-raw-ip-omf-5.echo"

echo "Aggregating statistics into single csv" >> "statistics-out/sroa-raw-ip-omf-5.echo"
python3 analysis/aggregate-memstates.py --stats-in="${TMP_STATS_DIR}/sroa-raw-ip-omf-5" --stats-out="statistics-out/sroa-raw-ip-omf-5.csv"

if [ ! -z "${CLEAN_TMP_STATS_DIR+x}" ]; then
rm -rf "${TMP_STATS_DIR}/sroa-raw-ip-omf-5"
fi
